fn immortal_brazier_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    let mut l_i = Val::from(0);
    let mut l_level_s: Vec<Val> = Vec::new();
    let mut l_map_s: Vec<Val> = Vec::new();
    ctx.lines(args!["- A Message is Engraved on the Brazier -", "The one who scatters the ashes of the darkness in this place shall become one step closer to Naght Sieger, the Hegemon King of the Darkness..."])?;
    ctx.next()?;
    let base = Val::from(1).number()?;
    runtime::local_set(&mut l_level_s, &Val::from(base + 0), Val::from("26th"), true);
    runtime::local_set(&mut l_level_s, &Val::from(base + 1), Val::from("51st"), true);
    runtime::local_set(&mut l_level_s, &Val::from(base + 2), Val::from("76th"), true);
    let base = Val::from(1).number()?;
    runtime::local_set(&mut l_map_s, &Val::from(base + 0), Val::from("2@tower"), true);
    runtime::local_set(&mut l_map_s, &Val::from(base + 1), Val::from("3@tower"), true);
    runtime::local_set(&mut l_map_s, &Val::from(base + 2), Val::from("4@tower"), true);
    l_i = Val::from(runtime::select_values(ctx, &[Val::from("26th Level:51st Level:76th Level")])?);
    if runtime::op(&ctx.call(Function::CountItem, vec![Val::from(6000)])?, "<", &l_i.clone())?.is_true() {
        ctx.lines(args![
            "-Warning-",
            ((((Val::from("To warp to the ") + runtime::local_get(&l_level_s, &l_i.clone(), true)) + Val::from(" Level, you need "))
                + l_i.clone())
                + Val::from(" Ashes of the Darkness."))
        ])?;
        ctx.close_window()?;
        return Err(Stop::End);
    }
    ctx.call(Function::DelItem, vec![Val::from(6000), l_i.clone()])?;
    ctx.call(
        Function::MapAnnounce,
        vec![
            ctx.call(Function::InstanceMapName, vec![Val::from("1@tower")])?,
            (((ctx.call(Function::StrCharInfo, vec![Val::from(0)])? + Val::from(". You will be warped to the "))
                + runtime::local_get(&l_level_s, &l_i.clone(), true))
                + Val::from(" Level.")),
            ctx.constant("BC_MAP")?,
            Val::from("0x00ff99"),
        ],
    )?;
    ctx.call(
        Function::Warp,
        vec![
            ctx.call(
                Function::InstanceMapName,
                vec![runtime::local_get(&l_map_s, &l_i.clone(), true)],
            )?,
            Val::from(52),
            Val::from(354),
        ],
    )?;
    ctx.close_window()?;
    return Err(Stop::End);
}

