fn manager_mode4_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    let mut l_i = Val::from(0);
    let mut l_input = Val::from(0);
    shared::other_gm_npcs::f_gm_npc(ctx, vec![])?;
    ctx.mes("Please enter the password.")?;
    l_i = shared::other_gm_npcs::f_gm_npc(ctx, vec![Val::from("dmc2008"), Val::from(1)])?;
    ctx.next()?;
    if l_i.clone() == 1 {
        ctx.lines(args![
            "This NPC manages the tower from the 76th to the 99th Level.",
            "Please enter the Level number to open.",
            "(i.g.: 76F->76, 99F->99)"
        ])?;
        let (input, status) = runtime::input_number(ctx, Some(76), Some(99))?;
        l_input = input;
        ctx.next()?;
        if (l_input.clone().number()? < 76 || l_input.clone().number()? > 99) {
            ctx.mes("You can only enter a number from 76 to 99.")?;
        } else {
            ctx.call(
                Function::DoNpcEvent,
                vec![
                    (ctx.call(Function::InstanceNpcName, vec![(l_input.clone() + Val::from("FGate102tower"))])? + Val::from("::OnEnable")),
                ],
            )?;
            ctx.lines(args![
                ((Val::from("*** Level ") + l_input.clone()) + Val::from(" is now being opened. ***"))
            ])?;
        }
    }
    ctx.close_window()?;
    return Err(Stop::End);
}

pub fn manager_mode4(ctx: &Ctx) -> Script {
    manager_mode4_body(ctx, Vec::new()).map(|_| ())
}

#[derive(Clone, Copy, Debug)]
enum LucidCrystal102Step {
    Start,
    OnInstanceInit,
    OnDisable,
    OnEnable,
}

fn lucid_crystal_102_run(ctx: &Ctx, mut step: LucidCrystal102Step, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            LucidCrystal102Step::Start => {
                if ctx.var("in_102tower").get()?.number()? < 10 {
                    ctx.mes(
                        "^0000ffA mysterious voice echoes through the room as you touch the lucid crystal radiating a strong light.^000000",
                    )?;
                    ctx.next()?;
                    ctx.lines_as(
                        "Mysterious Voice",
                        args!["Welcome to my place, intruders. I've had fun watching you endure all the difficulties I've set before you."],
                    )?;
                    ctx.next()?;
                    ctx.lines_as("Mysterious Voice", args!["Unfortunately, the time has come to end the show."])?;
                    ctx.next()?;
                    ctx.lines_as("Mysterious Voice", args!["It's still too early to celebrate your victory against my right-hand man Knothen because he isn't completely destroyed!"])?;
                    ctx.next()?;
                    ctx.lines_as(
                        "Mysterious Voice",
                        args!["I shall resurrect him for your next show. Defeat him again, and then I'll gladly accept your challenge."],
                    )?;
                    ctx.next()?;
                    ctx.lines_as(
                        "Mysterious Voice",
                        args![
                            "Good-bye for now.",
                            "Once again, I had such a great time, humans. I look forward to seeing you again."
                        ],
                    )?;
                    ctx.next()?;
                    ctx.mes("^0000ffAs soon as the voice stopped talking, an irresistible force lifted and moved you somewhere else.")?;
                    ctx.close_window()?;
                    ctx.var("in_102tower").set(Val::from(10))?;
                    ctx.call(Function::Warp, vec![Val::from("alberta"), Val::from(223), Val::from(36)])?;
                } else {
                    ctx.mes("^0000ffThe radiating crystal piece seems to beckon you, just like last time.^000000")?;
                    ctx.next()?;
                    ctx.lines_as(
                        "Mysterious Voice",
                        args!["I must have underestimated you... I didn't expect to see you again."],
                    )?;
                    ctx.next()?;
                    ctx.lines_as("Mysterious Voice", args!["I can smell your sweat, hear the gasps of your exhaustion in combat. Ah~ The human desire for victory always excites me."])?;
                    ctx.next()?;
                    ctx.lines_as("Mysterious Voice", args!["I now allow you to come receive an audience from me. Come to me, to Naght Sieger the Hegemon-King of the Darkness!"])?;
                    ctx.close_window()?;
                    ctx.call(
                        Function::Warp,
                        vec![
                            ctx.call(Function::InstanceMapName, vec![Val::from("6@tower")])?,
                            Val::from(32),
                            Val::from(12),
                        ],
                    )?;
                }
                return Err(Stop::End);
            }
            LucidCrystal102Step::OnInstanceInit => {
                step = LucidCrystal102Step::OnDisable;
                continue 'machine;
            }
            LucidCrystal102Step::OnDisable => {
                ctx.call(
                    Function::DisableNpc,
                    vec![ctx.call(Function::InstanceNpcName, vec![Val::from("Lucid Crystal#102")])?],
                )?;
                return Err(Stop::End);
            }
            LucidCrystal102Step::OnEnable => {
                ctx.call(
                    Function::EnableNpc,
                    vec![ctx.call(Function::InstanceNpcName, vec![Val::from("Lucid Crystal#102")])?],
                )?;
                ctx.call(
                    Function::DoNpcEvent,
                    vec![(ctx.call(Function::InstanceNpcName, vec![Val::from("#102Effect1")])? + Val::from("::OnEnable"))],
                )?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn lucid_crystal_102(ctx: &Ctx) -> Script {
    lucid_crystal_102_run(ctx, LucidCrystal102Step::Start, Vec::new()).map(|_| ())
}

pub fn lucid_crystal_102_oninstanceinit(ctx: &Ctx) -> Script {
    lucid_crystal_102_run(ctx, LucidCrystal102Step::OnInstanceInit, Vec::new()).map(|_| ())
}

pub fn lucid_crystal_102_ondisable(ctx: &Ctx) -> Script {
    lucid_crystal_102_run(ctx, LucidCrystal102Step::OnDisable, Vec::new()).map(|_| ())
}

pub fn lucid_crystal_102_onenable(ctx: &Ctx) -> Script {
    lucid_crystal_102_run(ctx, LucidCrystal102Step::OnEnable, Vec::new()).map(|_| ())
}

